289→  interface Range {
290→    getSheetId(): string;
291→    getRow(): number;
292→    getColumn(): number;
293→    getNumRows(): number;
294→    getNumColumns(): number;
295→    getA1Notation(): string;
296→
297→    getValue(): string | number | boolean | null;
298→    getValues(): any[][];
299→    setValue(value: any): void;
300→    setValues(values: any[][]): void;
301→    /** Three different erasers — pick by what must survive:
302→     *  clear() erases content AND styling, clearContent() erases values and
303→     *  formulas but keeps styling, clearFormat() erases styling but keeps
304→     *  content. All three are chainable. */
305→    clear(): Range;
306→    clearContent(): Range;
307→    clearFormat(): Range;
308→
309→    setFormula(formula: string): void;
310→    setFormulas(formulas: string[][]): void;
311→    getFormula(): string;
312→    getFormulas(): string[][];
313→    /** Audit this rectangle for formula-pattern consistency (R1C1-normalised):
314→     *  flags outlier formulas and non-formula gaps. Useful for the audit-spreadsheet flow. */
315→    auditFormulaConsistency(): FormulaConsistencyReport;
316→
317→    getNumberFormat(): string;
318→    getNumberFormats(): string[][];
319→    setNumberFormat(fmt: string): void;
320→    setNumberFormats(fmts: string[][]): void;
321→
322→    getBackground(): string;
323→    getBackgrounds(): string[][];
324→    setBackground(color: string | null): void;
325→    setBackgrounds(colors: (string | null)[][]): void;
326→
327→    setFontColor(color: string): void;
328→    setFontColors(colors: string[][]): void;
329→    getFontColor(): string;
330→    getFontColors(): string[][];
331→    setFontFamily(family: string): void;
332→    setFontFamilies(families: string[][]): void;
333→    getFontFamily(): string;
334→    getFontFamilies(): string[][];
335→    setFontSize(size: number): void;
336→    setFontSizes(sizes: number[][]): void;
337→    getFontSize(): number;
338→    getFontSizes(): number[][];
339→    setFontLine(line: "underline" | "line-through" | "none"): void;
340→    setFontLines(lines: string[][]): void;
341→    getFontLine(): string;
342→    getFontLines(): string[][];
343→    setFontWeight(weight: "bold" | "normal"): void;
344→    setFontWeights(weights: string[][]): void;
345→    getFontWeight(): string;
346→    getFontWeights(): string[][];
347→    setFontStyle(style: "italic" | "normal"): void;
348→    setFontStyles(styles: string[][]): void;
349→    getFontStyle(): string;
350→    getFontStyles(): string[][];
