369→    /** Merge regions overlapping this range (may extend outside it), and whether
370→     *  there is any. The read side of merging lives here and on Sheet — do NOT
371→     *  reach for other GAS-style spellings, they DO NOT EXIST. */
372→    getMergedRanges(): Range[];
373→    isPartOfMerge(): boolean;
