379→    getBorder(): { top: BorderSide | null; bottom: BorderSide | null; left: BorderSide | null; right: BorderSide | null };
380→    getBorders(): { top: BorderSide | null; bottom: BorderSide | null; left: BorderSide | null; right: BorderSide | null }[][];
381→    setBorder(
382→      top: boolean, left: boolean, bottom: boolean, right: boolean,
