435→  interface BorderSide {
436→    color: string;  // hex color e.g. "FF000000"
437→    style: string;  // "SOLID" | "SOLID_MEDIUM" | "SOLID_THICK" | "DASHED" | "DOTTED" | "DOUBLE" | "HAIR"
438→  }
439→
440→  interface TableInfo {
441→    startRow: number; startCol: number; endRow: number; endCol: number;
442→    orientation: "ROW" | "COLUMN" | "MATRIX";
443→    headers: string[]; numCols: number; numDataRows: number;
444→    cells: Record<string, any>;
445→    formulas: Record<string, string>;
446→    formats: Record<string, string>;
447→    hasMore: boolean;
