450→  enum FilterCriteriaType {
451→    VALUE = 0,
452→    COLOR = 1,
453→    CONDITION = 2,
454→  }
455→
456→  interface FilterColumnCriteria {
457→    // col: 0-based column index, e.g., to filter the 4th column, pass col = 3
458→    col: number;
